  1908	// buildChatRequest converts store.Chat to api.ChatRequest
  1909	func (s *Server) buildChatRequest(chat *store.Chat, model string, think any, availableTools api.Tools, mcpInstructions string) (*api.ChatRequest, error) {
  1910		var msgs []api.Message
  1911		// The servers' own words, ahead of the conversation. A tool definition says
  1912		// what one call does; this is the only place a server can say what it is
  1913		// for, which is what decides whether a model reaches for it unprompted.
  1914		if strings.TrimSpace(mcpInstructions) != "" {
  1915			msgs = append(msgs, api.Message{Role: "system", Content: mcpInstructions})
  1916		}
  1917		for _, m := range chat.Messages {
  1918			// Skip empty messages if present
  1919			if m.Content == "" && m.Thinking == "" && len(m.ToolCalls) == 0 && len(m.Attachments) == 0 {
  1920				continue
  1921			}
  1922	
  1923			apiMsg := api.Message{Role: m.Role, Thinking: m.Thinking}
  1924	
  1925			sb := strings.Builder{}
  1926			sb.WriteString(m.Content)
  1927	
  1928			var images []api.ImageData
  1929			if m.Role == "user" && len(m.Attachments) > 0 {
  1930				for _, a := range m.Attachments {
  1931					if isImageAttachment(a.Filename) {
  1932						images = append(images, api.ImageData(a.Data))
  1933					} else {
  1934						content := convertBytesToText(a.Data, a.Filename)
  1935						sb.WriteString(fmt.Sprintf("\n--- File: %s ---\n%s\n--- End of %s ---",
  1936							a.Filename, content, a.Filename))
  1937					}
  1938				}
  1939			}
  1940	
  1941			apiMsg.Content = sb.String()
  1942			apiMsg.Images = images
  1943	
  1944			switch m.Role {
  1945			case "assistant":
  1946				if len(m.ToolCalls) > 0 {
  1947					var toolCalls []api.ToolCall
  1948					for _, tc := range m.ToolCalls {
  1949						var args api.ToolCallFunctionArguments
  1950						if err := json.Unmarshal([]byte(tc.Function.Arguments), &args); err != nil {
  1951							s.log().Error("failed to parse tool call arguments", "error", err, "function_name", tc.Function.Name, "arguments", tc.Function.Arguments)
  1952							continue
  1953						}
  1954	
  1955						toolCalls = append(toolCalls, api.ToolCall{
  1956							Function: api.ToolCallFunction{
  1957								Name:      tc.Function.Name,
  1958								Arguments: args,
  1959							},
  1960						})
  1961					}
  1962					apiMsg.ToolCalls = toolCalls
  1963				}
  1964			case "tool":
  1965				apiMsg.Role = "tool"
  1966				apiMsg.Content = m.Content
  1967				apiMsg.ToolName = m.ToolName
  1968			case "user", "system":
  1969				// User and system messages are handled normally
  1970			default:
  1971				// Log unknown roles but still include them
  1972				s.log().Debug("unknown message role", "role", m.Role)
  1973			}
  1974	
  1975			msgs = append(msgs, apiMsg)
  1976		}
  1977	
  1978		var thinkValue *api.ThinkValue
  1979		if think != nil {
  1980			// Only set Think if it's actually requesting thinking
  1981			if boolValue, ok := think.(bool); ok {
  1982				if boolValue {
  1983					thinkValue = &api.ThinkValue{Value: boolValue}
  1984				}
  1985			} else if stringValue, ok := think.(string); ok {
  1986				if stringValue != "" && stringValue != "none" {
  1987					thinkValue = &api.ThinkValue{Value: stringValue}
  1988				}
  1989			}
  1990		}
  1991	
  1992		req := &api.ChatRequest{
  1993			Model:    model,
  1994			Messages: msgs,
  1995			Stream:   ptr(true),
  1996			Think:    thinkValue,
  1997		}
  1998	
  1999		if len(availableTools) > 0 {
  2000			req.Tools = availableTools
  2001		}
  2002	
  2003		return req, nil
  2004	}
